import{_ as r,C as l,o,c as i,a2 as e,b as s,w as n,a as g,E as d,a3 as A}from"./chunks/framework.DToEn73J.js";const B=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"AI Agent 工程入门","text":"面向资深工程师的设计资料站","tagline":"系统覆盖 Agent 工程核心主题 —— 去水分、直奔设计决策、每个知识点用「是什么 / 怎么做 / 为什么」三段式讲清。","actions":[{"theme":"brand","text":"从 Agent Loop 开始","link":"/01-agent-basics/agent-loop"},{"theme":"alt","text":"查看术语表","link":"/glossary"}]},"features":[{"icon":"🔁","title":"Agent 基础架构","details":"Agent Loop、工具抽象、结构化输出与函数调用、终止条件与预算控制、并发与竞态。","link":"/01-agent-basics/agent-loop","linkText":"第一章"},{"icon":"🧩","title":"能力扩展机制","details":"Skill 加载与管理、MCP 加载与扩展、权限与沙箱、多 Agent 编排与子 Agent 委派。","link":"/02-capability-extension/skill-management","linkText":"第二章"},{"icon":"🧠","title":"上下文与记忆","details":"上下文工程、上下文窗口管理、长期记忆管理、状态与会话持久化、RAG 检索增强。","link":"/03-context-memory/context-engineering","linkText":"第三章"},{"icon":"🗺️","title":"规划与执行","details":"Plan-and-Execute 模式切换、任务列表管理、错误处理与自我修正、模型路由与多模型编排。","link":"/04-planning-execution/plan-and-execute","linkText":"第四章"},{"icon":"🛡️","title":"安全与治理","details":"Prompt 防注入、审计和回滚、安全护栏与内容审核、紧急停止机制。","link":"/05-safety-governance/prompt-injection","linkText":"第五章"},{"icon":"⚙️","title":"工程化与运维","details":"Prompt 管理、可观测性（OTEL + Langfuse）、可评估性、成本与延迟优化、部署与扩展性。","link":"/06-engineering-ops/prompt-management","linkText":"第六章"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1788254264000}'),c={name:"index.md"};function h(E,t,u,p,k,m){const a=l("Mermaid");return o(),i("div",null,[t[1]||(t[1]=e('<h2 id="写在前面-我「重新发明」过的七个轮子" tabindex="-1">写在前面：我「重新发明」过的七个轮子 <a class="header-anchor" href="#写在前面-我「重新发明」过的七个轮子" aria-label="Permalink to &quot;写在前面：我「重新发明」过的七个轮子&quot;">​</a></h2><p>坦白讲，本站讲的大部分机制，我最初都不是从论文里学来的，而是在调 API 的过程中被逼出来的——先写了能跑的土办法，后来查资料才发现：每一条都有正式的学术名词，而且早已有人做了系统研究。下面按你大概率也会<strong>依次遇到</strong>的顺序，把这七个概念串一遍。它们不是七个并列的名词，而是一条<strong>演化链</strong>：地基是 API 的无状态本质，两端是「往窗口里塞什么」与「从窗口里取什么」，最上层是循环与封装。</p><h3 id="_1-上下文与记忆-——-大模型-api-的无状态本质" tabindex="-1">1. 上下文与记忆 —— 大模型 API 的无状态本质 <a class="header-anchor" href="#_1-上下文与记忆-——-大模型-api-的无状态本质" aria-label="Permalink to &quot;1. 上下文与记忆 —— 大模型 API 的无状态本质&quot;">​</a></h3><blockquote><p><strong>我的独立版本</strong>：第一次做多轮对话，发现模型「失忆」了。打开请求体才看明白：API 完全无状态，所谓「它记得」，其实是客户端每轮把全部历史消息重新打包发一遍。后来才知道，这个朴素事实是所有 LLM 应用的地基。</p></blockquote><ul><li><strong>定义</strong>：LLM API 是纯函数——输入 messages 数组，输出下一条消息，不保存任何状态。「记忆」由调用方自己维护、自己打包。</li><li><strong>核心机制</strong>：把 system / user / assistant / tool 消息按序拼进 Context Window（上下文窗口），构成模型全部的工作记忆；窗口有 token 上限，超限需裁剪或摘要压缩（compaction）。</li><li><strong>应用场景</strong>：会话持久化、多轮对话、上下文压缩、长期记忆系统——全部源于「历史归你管」这一事实。</li><li><strong>联系与区别</strong>：它是其余六个概念的<strong>前提</strong>。Few-Shot 与 RAG 管的是往窗口里<strong>塞什么</strong>，Tool Calling 管的是从窗口里<strong>取什么</strong>，其余都是在它之上搭的循环或封装。</li><li><strong>站内延伸</strong>：<a href="/fk-ai-agent/03-context-memory/context-window">上下文窗口管理</a>、<a href="/fk-ai-agent/03-context-memory/session-state">状态与会话持久化</a></li></ul><h3 id="_2-few-shot-——-不动权重-用例子「教」" tabindex="-1">2. Few-Shot —— 不动权重，用例子「教」 <a class="header-anchor" href="#_2-few-shot-——-不动权重-用例子「教」" aria-label="Permalink to &quot;2. Few-Shot —— 不动权重，用例子「教」&quot;">​</a></h3><blockquote><p><strong>我的独立版本</strong>：想让输出严格符合 JSON，光靠文字描述格式，模型十次错三次。后来直接在 prompt 里贴了两个输入/输出示例，立刻稳定。再后来发现这叫 In-Context Learning——GPT-3 那篇论文的标题就是它。</p></blockquote><ul><li><strong>定义</strong>：不更新模型权重，仅在输入中提供 K 个示例（K=0 即 Zero-Shot），模型从示例中归纳任务模式。</li><li><strong>核心机制</strong>：示例的选择、数量、顺序、摆放位置都显著影响效果；示例本身也消耗 token 预算，需与任务描述权衡。</li><li><strong>应用场景</strong>：输出格式约束、风格对齐、分类任务冷启动、结构化抽取。</li><li><strong>联系与区别</strong>：与微调相对——不动权重、即时生效、按 token 付费；与 RAG 同属「往上下文里塞内容」，区别是 Few-Shot 塞的是<strong>人工挑选的示例</strong>，RAG 塞的是<strong>按需检索的知识</strong>。</li><li><strong>站内延伸</strong>：<a href="/fk-ai-agent/03-context-memory/context-engineering">上下文工程</a></li></ul><h3 id="_3-rag-——-知识在窗口外面" tabindex="-1">3. RAG —— 知识在窗口外面 <a class="header-anchor" href="#_3-rag-——-知识在窗口外面" aria-label="Permalink to &quot;3. RAG —— 知识在窗口外面&quot;">​</a></h3><blockquote><p><strong>我的独立版本</strong>：模型不了解我的私有文档，全塞进去塞不下，于是先切块、每次只把最相关的几块塞进 prompt。后来发现这套流程有名字：Retrieval-Augmented Generation，2020 年的论文。</p></blockquote><ul><li><strong>定义</strong>：生成前先检索，把命中的知识注入 prompt，让模型基于给定材料作答。</li><li><strong>核心机制</strong>：离线：文档 → chunking → embedding → 向量库；在线：query → 检索（dense / sparse / hybrid，可加 rerank）→ 命中文块注入上下文。</li><li><strong>应用场景</strong>：私有知识问答、长文档问答、需要引用出处的场景。</li><li><strong>联系与区别</strong>：解决「知识在窗口外」的问题。注意它的检索是<strong>固定流水线</strong>（查一次、生成一次）——这正是它与 Agentic RAG 的分界点。</li><li><strong>站内延伸</strong>：<a href="/fk-ai-agent/03-context-memory/rag">RAG 检索增强</a></li></ul><h3 id="_4-tool-calling-——-让模型输出「我要调什么」" tabindex="-1">4. Tool Calling —— 让模型输出「我要调什么」 <a class="header-anchor" href="#_4-tool-calling-——-让模型输出「我要调什么」" aria-label="Permalink to &quot;4. Tool Calling —— 让模型输出「我要调什么」&quot;">​</a></h3><blockquote><p><strong>我的独立版本</strong>：想让模型查天气，我让它别直接回答，改输出一段 JSON（函数名 + 参数），外层代码解析并真正执行，再把结果作为 tool 消息喂回去。后来发现这叫 Function Calling（OpenAI，2023），学术源头是 Toolformer。</p></blockquote><ul><li><strong>定义</strong>：向模型声明可用工具及其 JSON Schema，模型在回复中输出结构化的调用请求；模型只负责「选择与填参」，<strong>执行永远在应用侧</strong>。</li><li><strong>核心机制</strong>：工具注册表（name + description + parameters schema）注入上下文 → 模型输出 tool call → 应用执行 → 结果回填消息序列。</li><li><strong>应用场景</strong>：一切模型需要与外界交互的场景：查数据库、调 API、写文件、发消息。</li><li><strong>联系与区别</strong>：Few-Shot / RAG 管输入侧，Tool Calling 是<strong>输出侧协议</strong>。它单次即可成立，但要完成多步任务还需要一个循环来承载——那就是 ReAct。</li><li><strong>站内延伸</strong>：<a href="/fk-ai-agent/01-agent-basics/structured-output">结构化输出与函数调用</a>、<a href="/fk-ai-agent/01-agent-basics/tool-abstraction">工具抽象</a></li></ul><h3 id="_5-react-——-把调用放进循环" tabindex="-1">5. ReAct —— 把调用放进循环 <a class="header-anchor" href="#_5-react-——-把调用放进循环" aria-label="Permalink to &quot;5. ReAct —— 把调用放进循环&quot;">​</a></h3><blockquote><p><strong>我的独立版本</strong>：一次 Tool Calling 干不完活，我把它套进 while 循环：模型要么继续调工具，要么宣布「完成」。后来发现这叫 ReAct（2022），是几乎所有 Agent 框架的运行时原型。</p></blockquote><ul><li><strong>定义</strong>：Reason + Act——模型交替进行推理（Thought）与行动（Action），观察执行结果（Observation）后继续，直至给出最终答案或触发终止条件。</li><li><strong>核心机制</strong>：Thought → Action → Observation 滚动循环；工程上必须配套终止条件（max_steps、预算、超时、重复调用检测），否则必然死循环。</li><li><strong>应用场景</strong>：一切 Agent 系统的运行时骨架——无论框架叫什么名字，内核都是这个循环（Agent Loop）。</li><li><strong>联系与区别</strong>：Tool Calling 是<strong>一次调用的协议</strong>，ReAct 是<strong>反复调用的骨架</strong>；在循环之上再加规划、任务列表与委派，就演化出 Plan-and-Execute 与多 Agent 编排。</li><li><strong>站内延伸</strong>：<a href="/fk-ai-agent/01-agent-basics/agent-loop">Agent Loop</a>、<a href="/fk-ai-agent/04-planning-execution/plan-and-execute">Plan-and-Execute</a></li></ul><h3 id="_6-agentic-rag-——-检索不再是必经步骤-而是工具" tabindex="-1">6. Agentic RAG —— 检索不再是必经步骤，而是工具 <a class="header-anchor" href="#_6-agentic-rag-——-检索不再是必经步骤-而是工具" aria-label="Permalink to &quot;6. Agentic RAG —— 检索不再是必经步骤，而是工具&quot;">​</a></h3><blockquote><p><strong>我的独立版本</strong>：检索一次常常不准，我干脆把「检索」注册成一个工具，让模型自己决定要不要查、用什么关键词查、结果不满意就换 query 再来一轮。后来发现这条路线已经自成流派：Self-RAG、CRAG、Agentic RAG。</p></blockquote><ul><li><strong>定义</strong>：把检索器降格为 Agent 可调用的工具之一，检索时机、query 改写、多源合并、结果自评都交给 Agent Loop 决策。</li><li><strong>核心机制</strong>：朴素 RAG 的固定流水线（检索 → 生成）变为动态决策——可多次检索、可改写 query、可判定「检索结果不足以作答」并补查。</li><li><strong>应用场景</strong>：多跳问题（答案依赖多个文档链）、研究型问答、跨数据源聚合。</li><li><strong>联系与区别</strong>：一句话——<strong>Agentic RAG = RAG + ReAct</strong>：知识注入策略（RAG）装进循环骨架（ReAct）。它也是理解「Agentic」一词的最好样本：把固定流水线改造成模型自主决策的工具编排。</li><li><strong>站内延伸</strong>：<a href="/fk-ai-agent/03-context-memory/rag">RAG 检索增强</a>、<a href="/fk-ai-agent/01-agent-basics/agent-loop">Agent Loop</a></li></ul><h3 id="_7-skill-——-把「怎么干活」打包成可加载的说明书" tabindex="-1">7. Skill —— 把「怎么干活」打包成可加载的说明书 <a class="header-anchor" href="#_7-skill-——-把「怎么干活」打包成可加载的说明书" aria-label="Permalink to &quot;7. Skill —— 把「怎么干活」打包成可加载的说明书&quot;">​</a></h3><blockquote><p><strong>我的独立版本</strong>：某类任务的系统提示词、工具说明、示例越积越多，全塞 system prompt 窗口装不下。于是拆成一个个独立文件，运行时按任务描述懒加载需要的那几份。后来发现这就是 Agent Skills 的做法，官方管这叫「渐进式披露」（progressive disclosure）。</p></blockquote><ul><li><strong>定义</strong>：将提示词、工具说明、参考资料与流程编排打包为独立、可复用、可按需加载的指令包（典型形态：一个带元数据的 Markdown 文件）。</li><li><strong>核心机制</strong>：运行时先只注入各 Skill 的名字与简介（极低 token 成本），Agent 判断需要时再加载完整内容；解决「能力总量 &gt;&gt; 窗口容量」的矛盾。</li><li><strong>应用场景</strong>：Agent 能力插件化——代码审查、数据分析、部署运维等各有独立 Skill，互不污染上下文。</li><li><strong>联系与区别</strong>：Tool 是模型的「手」，Skill 是教模型「怎么用手干这类活」的<strong>说明书</strong>；与 MCP 互补——MCP 解决工具<strong>接入</strong>协议，Skill 解决知识/流程的<strong>封装与复用</strong>。</li><li><strong>站内延伸</strong>：<a href="/fk-ai-agent/02-capability-extension/skill-management">Skill 加载与管理</a>、<a href="/fk-ai-agent/02-capability-extension/mcp">MCP 加载与扩展</a></li></ul><h3 id="七个概念-一张图" tabindex="-1">七个概念，一张图 <a class="header-anchor" href="#七个概念-一张图" aria-label="Permalink to &quot;七个概念，一张图&quot;">​</a></h3>',24)),(o(),s(A,null,{default:n(()=>[d(a,{id:"mermaid-254",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20C%5B%22%E4%B8%8A%E4%B8%8B%E6%96%87%E7%AA%97%E5%8F%A3%3Cbr%2F%3E%EF%BC%88%E6%97%A0%E7%8A%B6%E6%80%81%20API%20%2B%20%E5%8E%86%E5%8F%B2%E6%89%93%E5%8C%85%EF%BC%89%22%5D%0A%20%20%20%20C%20--%3E%7C%22%E5%BE%80%E9%87%8C%E5%A1%9E%E4%BB%80%E4%B9%88%22%7C%20F%5B%22Few-Shot%3Cbr%2F%3E%E6%B3%A8%E5%85%A5%E7%A4%BA%E4%BE%8B%22%5D%0A%20%20%20%20C%20--%3E%7C%22%E5%BE%80%E9%87%8C%E5%A1%9E%E4%BB%80%E4%B9%88%22%7C%20R%5B%22RAG%3Cbr%2F%3E%E6%B3%A8%E5%85%A5%E6%A3%80%E7%B4%A2%E7%9F%A5%E8%AF%86%22%5D%0A%20%20%20%20C%20--%3E%7C%22%E4%BB%8E%E4%B8%AD%E5%8F%96%E4%BB%80%E4%B9%88%22%7C%20T%5B%22Tool%20Calling%3Cbr%2F%3E%E8%BE%93%E5%87%BA%E7%BB%93%E6%9E%84%E5%8C%96%E8%B0%83%E7%94%A8%22%5D%0A%20%20%20%20T%20--%3E%7C%22%E6%94%BE%E8%BF%9B%E5%BE%AA%E7%8E%AF%22%7C%20A%5B%22ReAct%20%2F%20Agent%20Loop%22%5D%0A%20%20%20%20R%20--%3E%20A%0A%20%20%20%20A%20--%3E%20AR%5B%22Agentic%20RAG%3Cbr%2F%3E%3D%20RAG%20%2B%20ReAct%22%5D%0A%20%20%20%20R%20--%3E%20AR%0A%20%20%20%20A%20--%3E%20S%5B%22Skill%EF%BC%9A%E6%8F%90%E7%A4%BA%E8%AF%8D%20%2B%20%E5%B7%A5%E5%85%B7%20%2B%20%E6%B5%81%E7%A8%8B%3Cbr%2F%3E%E6%89%93%E5%8C%85%E6%87%92%E5%8A%A0%E8%BD%BD%22%5D%0A%20%20%20%20F%20--%3E%20S%0A"})]),fallback:n(()=>[...t[0]||(t[0]=[g(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e('<h3 id="速查表-区别与联系" tabindex="-1">速查表：区别与联系 <a class="header-anchor" href="#速查表-区别与联系" aria-label="Permalink to &quot;速查表：区别与联系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>解决的问题</th><th>所在层次</th><th>一句话联系</th></tr></thead><tbody><tr><td>上下文 / 记忆</td><td>API 无状态，「记忆」要自己打包</td><td>地基</td><td>其余六个概念的前提</td></tr><tr><td>Few-Shot</td><td>光靠指令说不清任务</td><td>输入侧 · 静态</td><td>往窗口里塞示例</td></tr><tr><td>RAG</td><td>知识在窗口外</td><td>输入侧 · 动态</td><td>往窗口里塞检索结果</td></tr><tr><td>Tool Calling</td><td>模型无法直接作用于外界</td><td>输出侧 · 协议</td><td>从窗口里取调用意图</td></tr><tr><td>ReAct</td><td>单次调用完不成多步任务</td><td>运行时 · 循环</td><td>Tool Calling × 循环</td></tr><tr><td>Agentic RAG</td><td>固定检索流水线不够聪明</td><td>组合模式</td><td>RAG + ReAct</td></tr><tr><td>Skill</td><td>能力总量远超窗口容量</td><td>封装复用层</td><td>提示词 / 工具 / 流程打包</td></tr></tbody></table><h2 id="这个站点是什么" tabindex="-1">这个站点是什么 <a class="header-anchor" href="#这个站点是什么" aria-label="Permalink to &quot;这个站点是什么&quot;">​</a></h2><p>本站是一份<strong>工程向</strong>的 AI Agent 设计资料，面向已有分布式系统、算法与基本 ML/LLM 背景的工程师。不解释「什么是 API」「什么是向量」这类基础概念，只聚焦 Agent 领域特有的设计决策与权衡。</p><p>全站按「从内到外」的工程分层组织为 6 章、24 个主题页，外加术语表与架构决策矩阵速查页。建议先按章节顺序通读，再用决策矩阵做索引式回顾。</p><h2 id="内容规范" tabindex="-1">内容规范 <a class="header-anchor" href="#内容规范" aria-label="Permalink to &quot;内容规范&quot;">​</a></h2><p>每个主题页统一采用三段式：</p><ol><li><strong>是什么</strong> —— 1–2 句定义问题域，不铺垫。</li><li><strong>怎么做</strong> —— 关键技术选择 + 最小可用实现思路，对比用表格、流程用 Mermaid 图。</li><li><strong>为什么</strong> —— 不这样做的后果，或与替代方案的权衡。</li></ol><p>涉及协议 / 规范 / 基准版本（如 MCP、OTEL + Langfuse、SWE-bench）的页面已 web search 核实当前版本，并在页底标注「最后核实日期」。</p>',9))])}const f=r(c,[["render",h]]);export{B as __pageData,f as default};
